mapper.select:
select * ,s.number * s.salebackprice AS sum from bus_salesback s join bus_customer c on s.customerid=c.id join bus_goods g on s.goodsid=g.id

	
	 and s.customerid =#{customerid}
	
	
	 and s.goodsid =#{goodsid}
	
	
	 and s.orderno =#{orderno}
	
	
	 and s.salesbacktime >= #{startTime}
	
	
	 and s.salesbacktime <= DATE_ADD(#{endTime}, INTERVAL 1 DAY)
	

limit #{index},#{limit}

 		select count(*) from bus_salesback s join bus_customer c on s.customerid=c.id join bus_goods g on s.goodsid=g.id
		
			
			 and s.customerid =#{customerid}
			
			
			 and s.goodsid =#{goodsid}
			
			
			 and s.orderno =#{orderno}
			
			
			 and s.salesbacktime >= #{startTime}
			
			
			 and s.salesbacktime <= DATE_ADD(#{endTime}, INTERVAL 1 DAY)
